const url = 'https://stooq.com/q/l/?s=es.f+nq.f+gc.f+dx.f&f=sd2t2ohlcv&h&e=csv';
const response = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
if (!response.ok) return [];
const csv = await response.text();
const lines = csv.trim().split(/\r?\n/);
const rows = lines.slice(1).map(line => line.split(','));
const labels = {
  'ES.F': 'ES',
  'NQ.F': 'NQ',
  'GC.F': 'Gold',
  'DX.F': 'DXY'
};
const quotes = rows
  .filter(row => row.length >= 7 && row[1] !== 'N/D')
  .map(row => {
    const [symbol, date, time, open, high, low, close] = row;
    const openNum = Number(open);
    const closeNum = Number(close);
    const pctFromOpen = openNum ? ((closeNum - openNum) / openNum) * 100 : 0;
    return {
      symbol,
      label: labels[symbol] || symbol,
      date,
      time,
      open: openNum,
      high: Number(high),
      low: Number(low),
      close: closeNum,
      pctFromOpen: Math.round(pctFromOpen * 100) / 100
    };
  });
if (!quotes.length) return [];
const by = Object.fromEntries(quotes.map(q => [q.label, q]));
let score = 0;
const reasons = [];
const es = by.ES;
const nq = by.NQ;
const dxy = by.DXY;
const gold = by.Gold;
if (es?.pctFromOpen <= -0.4) { score += 25; reasons.push(`ES weak ${es.pctFromOpen}%`); }
if (es?.pctFromOpen <= -0.8) score += 20;
if (nq?.pctFromOpen <= -0.6) { score += 25; reasons.push(`NQ weak ${nq.pctFromOpen}%`); }
if (nq?.pctFromOpen <= -1.2) score += 20;
if (dxy?.pctFromOpen >= 0.15) { score += 15; reasons.push(`DXY firm ${dxy.pctFromOpen}%`); }
if (dxy?.pctFromOpen >= 0.35) score += 10;
if (gold?.pctFromOpen >= 0.3) { score += 15; reasons.push(`Gold bid ${gold.pctFromOpen}%`); }
if (gold?.pctFromOpen >= 0.7) score += 10;
const equitiesRiskOff = (es?.pctFromOpen <= -0.4 ? 1 : 0) + (nq?.pctFromOpen <= -0.6 ? 1 : 0);
const safeHavenConfirm = (dxy?.pctFromOpen >= 0.15 ? 1 : 0) + (gold?.pctFromOpen >= 0.3 ? 1 : 0);
if (equitiesRiskOff >= 1 && safeHavenConfirm >= 1) { score += 20; reasons.push('Risk-off confluence'); }
if (equitiesRiskOff === 2) { score += 15; reasons.push('ES and NQ both weak'); }
let direction = 'neutral';
if (score >= 85) direction = 'risk_off';
let riskOnScore = 0;
const riskOnReasons = [];
if (es?.pctFromOpen >= 0.45) { riskOnScore += 25; riskOnReasons.push(`ES strong ${es.pctFromOpen}%`); }
if (nq?.pctFromOpen >= 0.65) { riskOnScore += 25; riskOnReasons.push(`NQ strong ${nq.pctFromOpen}%`); }
if (dxy?.pctFromOpen <= -0.15) { riskOnScore += 15; riskOnReasons.push(`DXY softer ${dxy.pctFromOpen}%`); }
if (gold?.pctFromOpen <= -0.3) { riskOnScore += 10; riskOnReasons.push(`Gold softer ${gold.pctFromOpen}%`); }
if ((es?.pctFromOpen >= 0.45 || nq?.pctFromOpen >= 0.65) && dxy?.pctFromOpen <= -0.15) riskOnScore += 20;
if (riskOnScore > score) {
  score = riskOnScore;
  direction = score >= 85 ? 'risk_on' : 'neutral';
  reasons.splice(0, reasons.length, ...riskOnReasons);
}
score = Math.min(140, score);
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const cooldownMs = 15 * 60 * 1000;
const key = `${direction}|${quotes.map(q => `${q.label}:${Math.round(q.pctFromOpen * 10) / 10}`).join('|')}`;
if (direction === 'neutral' || score < 85) return [];
if (staticData.lastAlertKey === key && now - (staticData.lastAlertAt || 0) < cooldownMs) return [];
staticData.lastAlertKey = key;
staticData.lastAlertAt = now;
const quoteLines = quotes.map(q => `${q.label}: ${q.close} (${q.pctFromOpen}%)`).join('\n');
return [{
  json: {
    direction,
    score,
    quoteLines,
    reasons: reasons.join('; '),
    source: 'Stooq delayed CSV',
    generatedAt: new Date().toISOString(),
    note: 'US10Y is intentionally not used until a reliable intraday source is configured.'
  }
}];
